window.__allInvoices = [];
window.__runQuery = async function(start, end) {
  document.querySelector('input[name=StartInvDate]').value = start;
  document.querySelector('input[name=EndInvDate]').value = end;
  document.getElementById('search_btn').click();
  await new Promise(r=>setTimeout(r,1800));
  let page = 1;
  while (true) {
    const table = [...document.querySelectorAll('table')].find(t=>t.innerText.includes('開立日期') && t.innerText.includes('發票號碼'));
    if (table) {
      const rows = [...table.querySelectorAll('tr')].slice(1);
      rows.forEach(tr => {
        const tds = [...tr.querySelectorAll('td')];
        if (tds.length < 7) return;
        const date = tds[0].textContent.trim();
        const invNum = tds[1].textContent.trim();
        const buyerTax = tds[3].textContent.trim();
        const buyerName = tds[4].textContent.trim();
        const amount = tds[5].textContent.trim();
        const combo = tds[6].textContent.trim();
        const m = combo.match(/^(\d{6})/);
        const customNum = m ? m[1] : combo.slice(0,6);
        const status = tds[7] ? tds[7].textContent.trim() : '';
        window.__allInvoices.push({date, invNum, buyerTax, buyerName, amount, customNum, status});
      });
    }
    const countTable = [...document.querySelectorAll('table')].find(t=>t.innerText.includes('總筆數'));
    const nextBtn = countTable ? countTable.querySelector('a.nextpage') : null;
    if (!nextBtn || !nextBtn.offsetParent) break;
    nextBtn.click();
    await new Promise(r=>setTimeout(r,1500));
    page++;
    if (page > 10) break;
  }
};
